3},{"text":"加入菠菜，用筷子輕輕壓入湯中。","step_no":4},{"text":"煮 1 至 2 分鐘至菠菜剛熟變軟。","step_no":5},{"text":"試味後連湯上碟即可。","step_no":6}],"ingredients":[{"id":"244b5f26-cb2f-440f-88f9-3adcb7185a97","name":"蒜頭","note":"切碎","unit":"clove","optional":false,"quantity":1},{"id":"92a6a27a-ad0b-4375-b166-935d7455c9ff","name":"鹽","note":null,"unit":"tsp","optional":true,"quantity":0.125},{"id":"a10b07f2-5c59-4f75-bc2d-ed79af879da9","name":"雞湯","note":null,"unit":"ml","optional":false,"quantity":150},{"id":"dd93c4fd-df93-4017-9fdd-e73c55d09dc4","name":"食油","note":null,"unit":"tsp","optional":false,"quantity":1},{"id":"ee18904d-df59-496e-9894-4d82f32f1f47","name":"菠菜","note":"洗淨","unit":"g","optional":false,"quantity":160}]},"guidanceBefore":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"33494ae30d8b9da495bb7f0cac1293c437f8b49125d86aee92565cab922f9e7e","cooking_tips":["菠菜入湯後輕壓浸入熱湯，菜葉軟化便檢查，避免一直煮到葉爛。","洗菠菜時把葉柄間的泥沙沖淨並瀝水，才不會把多餘洗菜水帶入湯內。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"guidanceAfter":{"version":1,"reviewed_on":"2026-11-15","review_method":"desk_review_not_test_cooked","source_fingerprint":"d0811169cdfecafca2bceab1b6cad72e893a16f3c82960b3f4ed540ae440554a","cooking_tips":["菠菜入湯後輕壓浸入熱湯，菜葉軟化便檢查，避免一直煮到葉爛。","洗菠菜時把葉柄間的泥沙沖淨並瀝水，才不會把多餘洗菜水帶入湯內。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]}}]$batch4$::jsonb);
DO $patch$
DECLARE item record; rid uuid; actual jsonb; protected jsonb; other_source jsonb; affected int;
 water_id uuid := '4d32e561-50ac-4bb4-be6e-43c12a72e397'; ml_id uuid;
BEGIN
 IF (SELECT count(*) FROM batch4_patch)<>3 THEN RAISE EXCEPTION 'Batch4 count changed'; END IF;
 PERFORM id FROM public.recipes WHERE id IN(SELECT(p->'after'->>'id')::uuid FROM batch4_patch) ORDER BY id FOR UPDATE;
 PERFORM recipe_id FROM public.recipe_ingredients WHERE recipe_id IN(SELECT(p->'after'->>'id')::uuid FROM batch4_patch) ORDER BY recipe_id,id FOR UPDATE;
 PERFORM recipe_id FROM public.recipe_steps WHERE recipe_id IN(SELECT(p->'after'->>'id')::uuid FROM batch4_patch) ORDER BY recipe_id,step_no FOR SHARE;
 IF (SELECT count(*) FROM public.units WHERE code='ml')<>1 OR NOT EXISTS(SELECT 1 FROM public.ingredients WHERE id=water_id AND name='水') THEN
  RAISE EXCEPTION 'Batch4 water/unit identity changed';
 END IF;
 SELECT id INTO ml_id FROM public.units WHERE code='ml' FOR SHARE;
 PERFORM id FROM public.ingredients WHERE id=water_id FOR SHARE;
 FOR item IN SELECT p FROM batch4_patch LOOP
  rid=(item.p->'after'->>'id')::uuid;
  SELECT to_jsonb(q) INTO actual FROM (select r.id,r.slug,r.name,r.description,r.method,r.meal_role,r.is_complete_meal,r.primary_protein,r.base_servings,r.total_time_minutes,r.diet,r.flavor,(select jsonb_agg(jsonb_build_object('step_no',s.step_no,'text',s.text) order by s.step_no) from public.recipe_steps s where s.recipe_id=r.id) as steps,(select jsonb_agg(jsonb_build_object('id',i.id,'name',i.name,'quantity',trim_scale(ri.quantity),'unit',u.code,'note',ri.prep_note,'optional',ri.is_optional) order by i.id) from public.recipe_ingredients ri join public.ingredients i on i.id=ri.ingredient_id left join public.units u on u.id=ri.unit_id where ri.recipe_id=r.id) as ingredients from public.recipes r where r.is_public=true) q WHERE q.id=rid;
  IF actual IS DISTINCT FROM item.p->'after' OR NOT EXISTS(SELECT 1 FROM public.recipes WHERE id=rid AND source_data->'editorial_guidance'=item.p->'guidanceAfter') THEN
   RAISE EXCEPTION 'Batch4 precondition changed: %',rid;
  END IF;
 END LOOP;
 FOR item IN SELECT p FROM batch4_patch LOOP
  rid=(item.p->'after'->>'id')::uuid;
  SELECT to_jsonb(r)-'source_data'-'updated_at',source_data-'editorial_guidance' INTO protected,other_source FROM public.recipes r WHERE id=rid;
  IF item.p->'after'->>'slug'='kimchi-egg-tofu' THEN
   DELETE FROM public.recipe_ingredients WHERE id='35340291-bba4-43ea-9a4d-38b79b809618' AND recipe_id=rid AND ingredient_id=water_id AND quantity=30 AND unit_id=ml_id AND is_optional=false AND prep_note='煮豆腐用；原步驟兩湯匙';
  ELSE
   UPDATE public.recipe_ingredients SET is_optional=false WHERE recipe_id=rid AND ingredient_id='92a6a27a-ad0b-4375-b166-935d7455c9ff';
  END IF;
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected<>1 THEN RAISE EXCEPTION 'Batch4 ingredient row count changed: %',rid; END IF;
  UPDATE public.recipes SET source_data=jsonb_set(source_data,'{editorial_guidance}',item.p->'guidanceBefore',true) WHERE id=rid;
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected<>1 OR NOT EXISTS(SELECT 1 FROM public.recipes r WHERE id=rid AND to_jsonb(r)-'source_data'-'updated_at'=protected AND source_data-'editorial_guidance'=other_source AND source_data->'editorial_guidance'=item.p->'guidanceBefore') THEN
   RAISE EXCEPTION 'Batch4 protected recipe changed: %',rid;
  END IF;
  SELECT to_jsonb(q) INTO actual FROM (select r.id,r.slug,r.name,r.description,r.method,r.meal_role,r.is_complete_meal,r.primary_protein,r.base_servings,r.total_time_minutes,r.diet,r.flavor,(select jsonb_agg(jsonb_build_object('step_no',s.step_no,'text',s.text) order by s.step_no) from public.recipe_steps s where s.recipe_id=r.id) as steps,(select jsonb_agg(jsonb_build_object('id',i.id,'name',i.name,'quantity',trim_scale(ri.quantity),'unit',u.code,'note',ri.prep_note,'optional',ri.is_optional) order by i.id) from public.recipe_ingredients ri join public.ingredients i on i.id=ri.ingredient_id left join public.units u on u.id=ri.unit_id where ri.recipe_id=r.id) as ingredients from public.recipes r where r.is_public=true) q WHERE q.id=rid;
  IF actual IS DISTINCT FROM item.p->'before' THEN RAISE EXCEPTION 'Batch4 final ingredients changed: %',rid; END IF;
 END LOOP;
END $patch$;
COMMIT;
